/**
 * Open a pull request for the current branch, pushing it first if needed.
 *
 * Opens a pull request from the checked-out branch with the given title, body, base, and draft flag. The branch is always the checked-out one, not the caller's to choose; when it is not yet published, it is pushed first, as opening a pull request from an unpushed branch cannot work. Refused with 409 when there is nothing to open (see GET /api/pull-request/draft) or the server is not running in a git repository, and 422 when the push fails, the title or base is missing, the forge turns the pull request down, with the forge's reason, or the repository's forge cannot be told apart, which says to set forge.kind and forge.host. Any other failed open is answered as a read's failure is: 502 when the forge cannot be reached or answers with a redirect, 503 with code rate_limited when it asks to wait (with Retry-After when it named the wait), 404 when it will not show the repository, and 422 when the forge token is missing or refused, or the forge settings are incomplete or reach no forge API. A reviewer either forge will not take, or an assignee GitLab does not know, does not stop the pull request: it opens with the reviewers and assignees the forge took, and the answer carries a warning.
 */
export const openPullRequest = <ThrowOnError extends boolean = false>(options: Options<OpenPullRequestData, ThrowOnError>): RequestResult<OpenPullRequestResponses, OpenPullRequestErrors, ThrowOnError> => (options.client ?? client).post<OpenPullRequestResponses, OpenPullRequestErrors, ThrowOnError>({
    responseValidator: async (data) => await zOpenPullRequestResponse.parseAsync(data),
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/api/pull-request',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

