/**
 * What you did over a period, grouped by year, month, day and hour.
 *
 * Reads back what you did from start to end of the days from and to, both included, in the server's own time zone: the commits you wrote in the repository the server runs in, the Taskwarrior tasks you added, annotated and completed and the ones you started that are still going, what you did to Jira issues, and the pull or merge requests you opened, had merged and reviewed on the forge, in any repository. Nothing is kept: every request reads the sources again. With neither day given it is the previous working day; with one, that day alone. Each source answers on its own, so one that cannot be read is named in sources with why, and the rest still answer. The period is refused with 422 when it runs backwards or is longer than a year and a day, or a day is not written as YYYY-MM-DD.
 */
export const getActivity = <ThrowOnError extends boolean = false>(options?: Options<GetActivityData, ThrowOnError>): RequestResult<GetActivityResponses, GetActivityErrors, ThrowOnError> => (options?.client ?? client).get<GetActivityResponses, GetActivityErrors, ThrowOnError>({
    responseValidator: async (data) => await zGetActivityResponse.parseAsync(data),
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/api/activity',
    ...options
});

/**
 * Post the Summary to the configured messaging service.
 *
 * Posts text — the Summary's Markdown for the days from and to, as GET /api/activity wrote it, or as a preview edited it — to the configured service: to the given channel, or the configured one when none is given, or the webhook's own channel. The Markdown is rendered for the service as it is posted: on Slack, which shows no heading, a heading is a bold line and an item a bullet; on Teams a heading is bold; on Discord the first three levels stay headings; and a plain webhook gets a heading's words alone. Nothing about the post is kept, as an announcement is. The period is refused with 422 as GET /api/activity refuses it, and so is blank text or text too long for the service; a service that refuses the post or is not set up is a 422, one that cannot be reached, or answers with a redirect, a 502, and one that asks to wait a 503 with code rate_limited, with Retry-After when it named the wait. No answer carries the service's own error, which can name the webhook. Under --dry-run it is refused with a plain-text 403, as every write is.
 */
export const postActivity = <ThrowOnError extends boolean = false>(options: Options<PostActivityData, ThrowOnError>): RequestResult<PostActivityResponses, PostActivityErrors, ThrowOnError> => (options.client ?? client).post<PostActivityResponses, PostActivityErrors, ThrowOnError>({
    responseValidator: async (data) => await zPostActivityResponse.parseAsync(data),
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/api/activity/post',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * A stream of state snapshots, pushed on connect and then every few seconds.
 *
 * A Server-Sent Events stream (text/event-stream). Each message is a "snapshot" event whose data is a Snapshot: the current issues, branch, changes, review, messaging destination, the issues in flight, the scope a new commit opens on, and a summary of your Taskwarrior tasks. The first is pushed on connect and another every few seconds after, whether or not anything changed: the upstreams send no notice of a change, so the server reads them again on that cadence. The browser subscribes once and updates from the pushes rather than polling. Each frame reads git and Taskwarrior afresh. The issues are the tracker's answer for the view, searched at most once every timing.ci_interval for every stream together, and again after a status change or an assignment made here. The review is the forge's answer, read at most once every timing.ci_interval (twenty seconds unless set) for every stream together, and again at once for another branch or head commit, or after a pull request is opened here. Neither read holds up a frame that has an answer held to show while another stream's read is under way. A read that fails keeps the last answer for the same branch and head commit, and with no answer to keep reports none found until a read succeeds. Which branches are for your issues is the tracker's answer too, asked again once a minute or when the branches name other issues; an ask that fails keeps the last answer, and with none lists every branch that names an issue. A search for Taskwarrior that finds none is not made again for a minute. An announcement held until CI passes (POST /api/announce with when ci_passes) is settled on each frame from the review it carries — posted once the CI has passed, dropped once it has failed — and the frame's queued_announcement says how it stands.
 */
export const streamEvents = <ThrowOnError extends boolean = false>(options?: Options<StreamEventsData, ThrowOnError, StreamEventsResponse>): Promise<ServerSentEventsResult<StreamEventsResponses>> => (options?.client ?? client).sse.get<StreamEventsResponses, StreamEventsErrors, ThrowOnError>({
    responseValidator: async (data) => await zStreamEventsResponse.parseAsync(data),
    security: [{ scheme: 'bearer', type: 'http' }, {
            in: 'query',
            name: 'session',
            type: 'apiKey'
        }],
    url: '/api/events',
    ...options
});

/**
 * Where the server works, and your favorite directories.
 *
 * The directory the server works in, the repository it is in and the path within it, origin's host and path, and the configuration files that apply there; then your favorite directories, each with what is there now. Each directory is also written from your home, as ~/src/api. Favorites are read from the store's kept file and looked at on disk each time.
 */
export const getRepositories = <ThrowOnError extends boolean = false>(options?: Options<GetRepositoriesData, ThrowOnError>): RequestResult<GetRepositoriesResponses, GetRepositoriesErrors, ThrowOnError> => (options?.client ?? client).get<GetRepositoriesResponses, GetRepositoriesErrors, ThrowOnError>({
    responseValidator: async (data) => await zGetRepositoriesResponse.parseAsync(data),
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/api/repositories',
    ...options
});

/**
 * Switch the directory the server works in.
 *
 * Wires the directory named as the server's first was wired — its repository, forge, the configuration files that apply there and the store's keys — and serves from it from then on; open event streams end, asking the page to reconnect, and every read after answers for the new directory. Refused with 404 when the directory is not there, 422 when it is not a directory or its configuration's ui.keys would be refused, and 409 while a write is in flight, which the switch would leave unknown. A write that carries a Workflow-Here header naming another directory than the server's is refused with 409, so a page still showing the old directory cannot write to the new one. Refused with 403 under --dry-run, by the guard every write passes.
 */
export const switchRepository = <ThrowOnError extends boolean = false>(options: Options<SwitchRepositoryData, ThrowOnError>): RequestResult<SwitchRepositoryResponses, SwitchRepositoryErrors, ThrowOnError> => (options.client ?? client).put<SwitchRepositoryResponses, SwitchRepositoryErrors, ThrowOnError>({
    responseValidator: async (data) => await zSwitchRepositoryResponse.parseAsync(data),
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/api/repositories/here',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

